-- Ansaro cinematic: gambar1 test (10.5s, loops)
local Players=game:GetService("Players")
local RS=game:GetService("RunService")
local AS=game:GetService("AssetService")
local SG=game:GetService("StarterGui")
pcall(function() SG:SetCoreGuiEnabled(Enum.CoreGuiType.All,false) end)
pcall(function() SG:SetCore("TopbarEnabled",false) end)
local cam=workspace.CurrentCamera
local cast=workspace:WaitForChild("Cast")
local guy=cast:WaitForChild("Guy") local girl=cast:WaitForChild("Girl")
local bouquet=workspace:WaitForChild("Bouquet")
local coffin=workspace:WaitForChild("Coffin")
-- faces
local N=128
local IMG={}
for name,data in FACES do
  local buf=buffer.create(N*N*4) local o=0
  for item in string.gmatch(data,"[^,]+") do
    local ci,cnt=string.match(item,"(%d+):(%d+)") local c=PAL[tonumber(ci)+1]
    for _=1,tonumber(cnt) do buffer.writeu8(buf,o,c[1]) buffer.writeu8(buf,o+1,c[2]) buffer.writeu8(buf,o+2,c[3]) buffer.writeu8(buf,o+3,c[4]) o+=4 end
  end
  local ok,img=pcall(function() return AS:CreateEditableImage({Size=Vector2.new(N,N)}) end)
  if ok and img then img:WritePixelsBuffer(Vector2.zero,Vector2.new(N,N),buf) IMG[name]=Content.fromObject(img) else warn("EditableImage fail",img) end
end
local function faceDecal(m) local h=m.Head for _,d in h:GetChildren() do if d:IsA("Decal") then return d end end local d=Instance.new("Decal") d.Name="face" d.Face=Enum.NormalId.Front d.Parent=h return d end
local gFace,lFace=faceDecal(guy),faceDecal(girl)
local cur={}
local function setFace(dec,name) if cur[dec]==name then return end cur[dec]=name local c=IMG[name] if c then dec.TextureContent=c end end
-- motors
local function motors(m) local t={} for _,d in m:GetDescendants() do if d:IsA("Motor6D") then t[d.Name]={m=d,c0=d.C0} end end return t end
local GM,LM=motors(guy),motors(girl)
local function rot(M,name,x,y,z) local e=M[name] if e then e.m.C0=e.c0*CFrame.Angles(math.rad(x or 0),math.rad(y or 0),math.rad(z or 0)) end end
local function resetPose(M) for _,e in M do e.m.C0=e.c0 end end
-- subtitles
local pg=Players.LocalPlayer:WaitForChild("PlayerGui")
local gui=Instance.new("ScreenGui") gui.Name="Subs" gui.IgnoreGuiInset=true gui.ResetOnSpawn=false gui.DisplayOrder=10 gui.Parent=pg
local black=Instance.new("Frame") black.Size=UDim2.fromScale(1,1) black.BackgroundColor3=Color3.new(0,0,0) black.BorderSizePixel=0 black.Parent=gui
local lbl=Instance.new("TextLabel") lbl.BackgroundTransparency=1 lbl.AnchorPoint=Vector2.new(0.5,0.5) lbl.Position=UDim2.fromScale(0.5,0.66) lbl.Size=UDim2.fromScale(0.4,0.12)
lbl.Font=Enum.Font.GothamBlack lbl.TextScaled=true lbl.TextColor3=Color3.new(1,1,1) lbl.Text="" lbl.Parent=gui
local st=Instance.new("UIStroke") st.Thickness=5 st.Color=Color3.new(0,0,0) st.Parent=lbl
local tsc=Instance.new("UITextSizeConstraint") tsc.MaxTextSize=64 tsc.Parent=lbl
local WORDS={{0.15,"I'M"},{0.45,"THE"},{0.7,"SHYEST"},{1.6,"PERSON"},{2.15,"EVER"},{3.0,"WHEN"},{3.25,"I"},{3.45,"SEE"},{3.75,"MY"},{3.95,"CRUSH"},{4.55,"I"},{4.7,"TRIED"},{5.0,"TO"},{5.2,"GIVE"},{5.45,"HER"},{5.7,"FLOWERS"},{6.5,"AND"},{6.75,"TRIPPED"},{8.05,"OH"},{8.35,"MY..."},{9.1,"R.I.P."},{9.6,"🥀"}}
local function word(t) local w="" for _,x in WORDS do if t>=x[1] then w=x[2] end end return w end
-- helpers
local function lerp(a,b,t) return a+(b-a)*math.clamp(t,0,1) end
local function ease(t) t=math.clamp(t,0,1) return t*t*(3-2*t) end
local function shake(amp,t) return CFrame.Angles(math.rad(amp*math.noise(t*9,1)),math.rad(amp*math.noise(t*9,2)),0) end
local function look(pos,target,roll) return CFrame.lookAt(pos,target)*CFrame.Angles(0,0,math.rad(roll or 0)) end
local FLOOR=0.1
local function stand(m,x,z,yaw) m:PivotTo(CFrame.new(x,FLOOR+2.95,z)*CFrame.Angles(0,math.rad(yaw),0)) end
local GUY_YAW=-90 -- faces +X
local function holdFlowers(M) rot(M,"RightShoulder",70,0,-10) rot(M,"LeftShoulder",70,0,15) rot(M,"RightElbow",30,0,0) rot(M,"LeftElbow",30,0,0) end
local function bouquetTo(cf) bouquet:PivotTo(cf) end
local function inHand() local h=guy.RightHand bouquetTo(h.CFrame*CFrame.new(-0.4,-0.5,-0.2)*CFrame.Angles(math.rad(-90),0,0)) end
local LOOP=12.5
local t0=os.clock()+2
cam.CameraType=Enum.CameraType.Scriptable
RS:BindToRenderStep("Cine",Enum.RenderPriority.Camera.Value+1,function()
  cam.CameraType=Enum.CameraType.Scriptable
  local T=os.clock()-t0
  if T<0 then black.Visible=true lbl.Text="" return end
  T=T%LOOP
  if T>10.6 then black.Visible=true lbl.Text="" return end
  black.Visible=false
  lbl.Text=word(T)
  resetPose(GM) resetPose(LM)
  cam.FieldOfView=60
  -- default placement
  stand(girl,4,1,90) setFace(lFace,"girl_neutral")
  rot(LM,"RightShoulder",0,0,-8) rot(LM,"LeftShoulder",0,0,8)
  if T<1.5 then -- S1 hook close-up, dutch + shake
    stand(guy,-4,1,GUY_YAW) holdFlowers(GM) inHand() setFace(gFace,"guy_scared")
    local hp=guy.Head.Position
    local p=hp+Vector3.new(2.3-T*0.4,0.3,0.4)
    cam.FieldOfView=50
    cam.CFrame=look(p,hp+Vector3.new(0,0.05,0),-28+T*6)*shake(4*(1.5-T),T)
  elseif T<3.0 then -- S2 medium, push in, shy
    local u=(T-1.5)/1.5
    stand(guy,-4,1,GUY_YAW) holdFlowers(GM) rot(GM,"Neck",-10,0,8) inHand() setFace(gFace,"guy_shy")
    local hp=guy.Head.Position
    cam.CFrame=look(hp+Vector3.new(lerp(7.5,5.5,ease(u)),-0.6,lerp(2,1,u)),hp+Vector3.new(0,-1.3,0),4)
  elseif T<4.5 then -- S3 over-shoulder to crush
    local u=(T-3)/1.5
    stand(guy,-4,1,GUY_YAW) holdFlowers(GM) inHand() setFace(gFace,"guy_shy")
    rot(LM,"Neck",0,lerp(0,-15,u),0) rot(LM,"RightShoulder",0,0,-8-6*math.sin(T*4))
    local gp=girl.Head.Position
    cam.CFrame=look(guy.Head.Position+Vector3.new(-1.2,0.8,1.4),gp+Vector3.new(0,-0.6,0),0)
    cam.FieldOfView=lerp(55,42,ease(u))
  elseif T<6.5 then -- S4 walk with flowers, side track
    local u=(T-4.5)/2
    local x=lerp(-4,0.2,u)
    stand(guy,x,1,GUY_YAW) holdFlowers(GM) setFace(gFace,"guy_nervous")
    local s=math.sin(T*11)*35 rot(GM,"RightHip",s,0,0) rot(GM,"LeftHip",-s,0,0)
    guy:PivotTo(guy:GetPivot()+Vector3.new(0,math.abs(math.sin(T*11))*0.15,0))
    inHand()
    local gp=guy.Head.Position
    cam.CFrame=look(Vector3.new(x+1.5,3.6,9.2),gp+Vector3.new(1.4,-1.8,0),0)
  elseif T<8.0 then -- S5 trip & fall
    local u=(T-6.5)
    local fall=ease(u/0.45)
    local base=CFrame.new(0.2,FLOOR,1)*CFrame.Angles(0,math.rad(GUY_YAW),0)
    -- pivot at feet, tip forward (character faces +X => rotate around its local X)
    local body=base*CFrame.Angles(math.rad(-88*fall),0,0)*CFrame.new(0,2.95,0)
    guy:PivotTo(body+Vector3.new(0,0.5*fall,0))
    rot(GM,"RightShoulder",lerp(70,160,fall),0,-20) rot(GM,"LeftShoulder",lerp(70,160,fall),0,20)
    rot(GM,"RightHip",-25*fall,0,0)
    setFace(gFace,"guy_shock")
    -- bouquet flies forward
    local bp=Vector3.new(lerp(1.2,6.5,ease(u/0.7)),lerp(3,0.6,ease(u/0.7))+math.sin(math.clamp(u/0.7,0,1)*math.pi)*2.5,1.2)
    bouquetTo(CFrame.new(bp)*CFrame.Angles(u*9,u*4,0))
    local imp=(u>0.42 and u<0.9) and (0.9-u)*14 or 0
    cam.FieldOfView=55
    cam.CFrame=look(Vector3.new(-3.5,1.0,6),Vector3.new(1.8,1.2,1),-10)*shake(imp,T)
  elseif T<9.0 then -- S6 crush shocked close-up
    local u=T-8
    guy:PivotTo(CFrame.new(0.2,FLOOR+0.6,1)*CFrame.Angles(0,math.rad(GUY_YAW),0)*CFrame.Angles(math.rad(-88),0,0)*CFrame.new(0,2.95,0))
